-- C2 extension. The existing world revision is the sole canonical revision.
CREATE TABLE IF NOT EXISTS item_definitions(id TEXT PRIMARY KEY NOT NULL,origin TEXT NOT NULL CHECK(origin IN ('official','custom','legacy_unresolved')),catalog_category TEXT,catalog_id TEXT,catalog_revision TEXT,name TEXT NOT NULL,unit_weight_lb REAL CHECK(unit_weight_lb IS NULL OR (typeof(unit_weight_lb) IN ('integer','real') AND unit_weight_lb>=0)),attributes TEXT NOT NULL,source_event_id INTEGER REFERENCES events(id),CHECK(origin<>'custom' OR source_event_id IS NOT NULL),UNIQUE(catalog_category,catalog_id,catalog_revision));
CREATE TABLE IF NOT EXISTS loot_containers(id TEXT PRIMARY KEY NOT NULL,location_id TEXT NOT NULL REFERENCES locations(id),source_kind TEXT NOT NULL CHECK(source_kind IN ('discovery','drop','encounter_outcome')),source_key TEXT NOT NULL,source_actor_id TEXT REFERENCES actors(id),source_event_id INTEGER NOT NULL REFERENCES events(id),name TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('player','private')),status TEXT NOT NULL CHECK(status IN ('available','closed')),UNIQUE(source_kind,source_key));
CREATE TABLE IF NOT EXISTS item_instances(id TEXT PRIMARY KEY NOT NULL,definition_id TEXT NOT NULL REFERENCES item_definitions(id),actor_id TEXT REFERENCES actors(id),container_id TEXT REFERENCES loot_containers(id),quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 2147483647),charges INTEGER CHECK(charges IS NULL OR (typeof(charges)='integer' AND charges>=0)),condition TEXT NOT NULL CHECK(condition IN ('unknown','intact','worn','damaged','broken')),attunement TEXT NOT NULL CHECK(attunement IN ('unknown','not_required','unattuned','attuned')),provenance TEXT NOT NULL,source_event_id INTEGER REFERENCES events(id),CHECK((actor_id IS NOT NULL)+(container_id IS NOT NULL)=1),UNIQUE(id,actor_id));
CREATE TABLE IF NOT EXISTS equipment_assignments(actor_id TEXT NOT NULL REFERENCES actors(id),slot TEXT NOT NULL CHECK(slot IN ('head','cloak','body','hands','feet','neck','ring','accessory','belt','shield','main_hand','off_hand')),instance_id TEXT NOT NULL,grip TEXT NOT NULL CHECK(grip IN ('worn','one_handed','two_handed')),PRIMARY KEY(actor_id,slot),FOREIGN KEY(instance_id,actor_id) REFERENCES item_instances(id,actor_id));
CREATE TABLE IF NOT EXISTS equipment_review(actor_id TEXT NOT NULL REFERENCES actors(id),instance_id TEXT NOT NULL REFERENCES item_instances(id),reason TEXT NOT NULL,PRIMARY KEY(actor_id,instance_id));
CREATE TABLE IF NOT EXISTS actor_templates(id TEXT PRIMARY KEY NOT NULL,catalog_category TEXT NOT NULL,catalog_id TEXT NOT NULL,catalog_revision TEXT NOT NULL,stat_block TEXT NOT NULL,UNIQUE(catalog_category,catalog_id,catalog_revision));
CREATE TABLE IF NOT EXISTS actor_instances(actor_id TEXT PRIMARY KEY NOT NULL REFERENCES actors(id),template_id TEXT REFERENCES actor_templates(id),generation_key TEXT NOT NULL UNIQUE,source_event_id INTEGER NOT NULL REFERENCES events(id),visibility TEXT NOT NULL CHECK(visibility IN ('player','private')),sheet_visibility TEXT NOT NULL CHECK(sheet_visibility IN ('public','private')),sheet TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS loot_currency(container_id TEXT NOT NULL REFERENCES loot_containers(id),denomination TEXT NOT NULL CHECK(denomination IN ('cp','sp','ep','gp','pp')),quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 0 AND 2147483647),PRIMARY KEY(container_id,denomination));
CREATE TABLE IF NOT EXISTS gameplay_requests(request_id TEXT PRIMARY KEY NOT NULL,actor_id TEXT NOT NULL REFERENCES actors(id),kind TEXT NOT NULL,expected_revision INTEGER NOT NULL CHECK(typeof(expected_revision)='integer' AND expected_revision>=0),logical_turn_id TEXT,status TEXT NOT NULL CHECK(status IN ('accepted_pending','committed','rejected','cancelled')),request_payload TEXT NOT NULL,result_payload TEXT NOT NULL,settled_revision INTEGER NOT NULL CHECK(typeof(settled_revision)='integer' AND settled_revision>=0),event_id INTEGER REFERENCES events(id),CHECK(status<>'committed' OR event_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS item_transfers(id TEXT PRIMARY KEY NOT NULL,request_id TEXT NOT NULL REFERENCES gameplay_requests(request_id),source_instance_id TEXT NOT NULL,destination_instance_id TEXT NOT NULL,definition_id TEXT NOT NULL REFERENCES item_definitions(id),quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity>0),source_container_id TEXT REFERENCES loot_containers(id),destination_actor_id TEXT REFERENCES actors(id),source_event_id INTEGER NOT NULL REFERENCES events(id));
CREATE TABLE IF NOT EXISTS party_members(actor_id TEXT PRIMARY KEY NOT NULL REFERENCES actors(id),source_event_id INTEGER NOT NULL REFERENCES events(id),status TEXT NOT NULL CHECK(status IN ('member','departed')),visibility TEXT NOT NULL CHECK(visibility IN ('player','private')));
CREATE TABLE IF NOT EXISTS story_records(id TEXT PRIMARY KEY NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('overview','situation','quest','objective','relationship','animosity','repeat_offender','faction','debt','promise','unresolved_event','circumstance')),identity_key TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('offered','active','completed','failed','abandoned','resolved','open','closed')),visibility TEXT NOT NULL CHECK(visibility IN ('player','private')),certainty TEXT NOT NULL CHECK(certainty IN ('fact','rumour','attitude')),location_id TEXT REFERENCES locations(id),parent_id TEXT REFERENCES story_records(id),source_event_id INTEGER NOT NULL REFERENCES events(id),updated_event_id INTEGER NOT NULL REFERENCES events(id),progress_current INTEGER CHECK(progress_current IS NULL OR (typeof(progress_current)='integer' AND progress_current>=0)),progress_max INTEGER CHECK(progress_max IS NULL OR (typeof(progress_max)='integer' AND progress_max>0)),CHECK((progress_current IS NULL)=(progress_max IS NULL)),CHECK(progress_current IS NULL OR progress_current<=progress_max));
CREATE TABLE IF NOT EXISTS story_participants(record_id TEXT NOT NULL REFERENCES story_records(id),actor_id TEXT NOT NULL REFERENCES actors(id),role TEXT NOT NULL,PRIMARY KEY(record_id,actor_id,role));
CREATE TABLE IF NOT EXISTS story_history(id INTEGER PRIMARY KEY,record_id TEXT NOT NULL REFERENCES story_records(id),event_id INTEGER NOT NULL REFERENCES events(id),request_id TEXT NOT NULL REFERENCES gameplay_requests(request_id),snapshot TEXT NOT NULL,UNIQUE(record_id,request_id));
CREATE INDEX IF NOT EXISTS c2_item_owner ON item_instances(actor_id,definition_id);
CREATE INDEX IF NOT EXISTS c2_item_container ON item_instances(container_id);
CREATE INDEX IF NOT EXISTS c2_loot_location ON loot_containers(location_id,status,visibility);
CREATE INDEX IF NOT EXISTS c2_story_location ON story_records(location_id,status,visibility);
CREATE INDEX IF NOT EXISTS c2_story_participant ON story_participants(actor_id);
CREATE INDEX IF NOT EXISTS c2_request_actor ON gameplay_requests(actor_id,settled_revision);
CREATE INDEX IF NOT EXISTS c2_story_event ON story_history(event_id);
